def validateBinaryTreeNodes(n, leftChild, rightChild):
    if n == 0:
        return True

    in_degree = [0] * n

    for i in range(n):
        if leftChild[i] != -1:
            in_degree[leftChild[i]] += 1
        if rightChild[i] != -1:
            in_degree[rightChild[i]] += 1

    root_candidates = [i for i in range(n) if in_degree[i] == 0]

    if len(root_candidates) != 1:
        return False

    root = root_candidates[0]
    visited = set()
    stack = [root]

    while stack:
        node = stack.pop()
        if node in visited:
            return False
        visited.add(node)
        if leftChild[node] != -1:
            stack.append(leftChild[node])
        if rightChild[node] != -1:
            stack.append(rightChild[node])

    return len(visited) == n
